import { z } from "zod";

export const getExpertSchema = (t: (key: string) => string) => z.object({
  email: z.string().min(1, t("experts.edit.form.validation.emailRequired") || "Email is required").email(t("experts.edit.form.validation.invalidEmail") || "Invalid email address"),
  phone_number: z.string().min(1, t("experts.edit.form.validation.phoneRequired") || "Phone number is required"),
  display_name: z.string().min(1, t("experts.edit.form.validation.nameRequired") || "Full Name is required").max(128, t("experts.edit.form.validation.nameMaxLength") || "Name must be less than 128 characters"),
  title: z.string().max(128, t("experts.edit.form.validation.titleMaxLength") || "Title must be less than 128 characters").optional().or(z.literal("")),
  bio: z.string().optional().or(z.literal("")),
  years_experience: z.number().min(0, t("experts.edit.form.validation.yearsMin") || "Years of experience must be at least 0").optional().or(z.literal("")),
  certifications: z.array(
    z.object({
      cert_name: z.string().max(128, t("experts.edit.form.validation.certMaxLength") || "Certification name must be less than 128 characters").optional().or(z.literal(""))
    })
  ).optional(),
  website: z.string().url(t("experts.edit.form.validation.invalidUrl") || "Invalid URL").max(255).optional().or(z.literal("")),
  linkedin: z.string().url(t("experts.edit.form.validation.invalidUrl") || "Invalid URL").max(255).optional().or(z.literal("")),
  languages: z.array(z.union([z.string(), z.number()])).min(1, t("experts.edit.form.validation.selectLanguage") || "Select at least one language"),
  categories: z.array(z.number()).min(1, t("experts.edit.form.validation.selectCategory") || "Select at least one specialization"),
  countries: z.array(z.number()).min(1, t("experts.edit.form.validation.selectCountry") || "Select at least one service area"),
  podcast: z.boolean().optional(),
  image: z.any().optional()
});

export type ExpertFormValues = z.infer<ReturnType<typeof getExpertSchema>>;

